/// Compute PDA for `airdrop` account.
/// Seeds: [const("airdrop"), arg(airdrop_id)]
pub fn compute_airdrop_pda(program_id: &ProgramId, airdrop_id: &[u8; 32]) -> AccountId {
    use sha2::{Sha256, Digest};
    let mut hasher = Sha256::new();
    {
        let mut padded = [0u8; 32];
        let src = b"airdrop";
        padded[..src.len()].copy_from_slice(src);
        hasher.update(&padded);
    }
    hasher.update(airdrop_id as &[u8]);
    let combined: [u8; 32] = hasher.finalize().into();
    let pda_seed = nssa_core::program::PdaSeed::new(combined);
    AccountId::for_public_pda(program_id, &pda_seed)
}

